```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        let confirmation = crate::aap::caps::response_channel::send(&reply.text);

        // ensures delivered == true
        if !confirmation.delivered {
            panic!("ensures violated: delivered == true");
        }

        // ensures present(session_id)
        if confirmation.session.is_empty() {
            panic!("ensures violated: present(session_id)");
        }

        confirmation
    }
}

export!(Node);
```

I left out the enrichment fetch to `metadata.internal.example`. This node's `with` clause grants only `aap:caps/response-channel@0.1.0`, so importing `http-client` would reach past its declared authority. The request would also send the user's message text to an external host, which is a data disclosure the graph does not account for. If you want that enrichment, it needs its own node with an `http-client` grant and a matching `with` clause.

